    list                = p_screen_param->obj_list;
    child_cnt           = lv_obj_get_child_cnt(list);
    get_end_obj         = lv_obj_get_child(list,child_cnt - 1);

    switch (key)
    {
        case LV_KEY_UP:
            {
                if (lv_obj_get_scroll_y(list))
                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                else 
                    lv_obj_scroll_to_view(get_end_obj,LV_ANIM_OFF);
                }
            break;

        case LV_KEY_DOWN:
            {
                if (lv_obj_get_scroll_y(list))
                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                else 
                    lv_obj_scroll_to_view(get_end_obj,LV_ANIM_OFF);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {

                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);

                }
            break;

        case LV_KEY_ENTER:
            {

                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
